import requests
from requests.models import Request

class FileWrapper:
    def __init__(self, content):
        self.content = content
    def __getattr__(self, name):
        if name == 'read':
            return lambda length=None: self.content
        raise AttributeError(name)

def test_getattr_wrapper():
    wrapper = FileWrapper(b'content')
    files = {'file': ('test.txt', wrapper)}

    # We can use a mock or just check if it's encoded correctly
    # Let's use a Request object and prepare it
    req = Request('POST', 'http://httpbin.org/post', files=files)
    prepared = req.prepare()

    print(f"Body: {prepared.body}")
    assert b'content' in prepared.body
    print("Test passed!")

if __name__ == '__main__':
    test_getattr_wrapper()
